type ShopContextValue = { cart: CartItem[]; add: (item: Omit<CartItem, "quantity">) => void; change: (item: CartItem, delta: number) => void; remove: (item: CartItem) => void; openCart: () => void };
const ShopContext = createContext<ShopContextValue | null>(null);
function useShop() { const value = useContext(ShopContext); if (!value) throw new Error("Shop context unavailable"); return value; }

