function Dialog({ title, children, onClose, wide = false }: { title: string; children: ReactNode; onClose: () => void; wide?: boolean }) {
  const closeRef = useRef<HTMLButtonElement>(null);
  useEffect(() => { closeRef.current?.focus(); const onKey = (event: KeyboardEvent) => event.key === "Escape" && onClose(); document.body.style.overflow = "hidden"; return () => { document.body.style.overflow = ""; window.removeEventListener("keydown", onKey); }; }, [onClose]);
  return <div className="fixed inset-0 z-50 grid place-items-center bg-[#261914]/60 p-4 backdrop-blur-sm" onMouseDown={(event) => event.target === event.currentTarget && onClose()}><div role="dialog" aria-modal="true" aria-labelledby="dialog-title" className={`relative max-h-[92dvh] w-full ${wide ? "max-w-2xl" : "max-w-md"} overflow-y-auto rounded-[1.7rem] bg-[#FBF5ED] p-6 shadow-2xl sm:p-8`}><button ref={closeRef} type="button" onClick={onClose} className="absolute right-4 top-4 rounded-full p-2 hover:bg-[#F1E2D1]" aria-label="Fermer"><X size={19} /></button><h2 id="dialog-title" className="sr-only">{title}</h2>{children}</div></div>;
}

