function AddButton({ item, onDone }: { item: Omit<CartItem, "quantity">; onDone?: () => void }) { const { add } = useShop(); return <button type="button" onClick={() => { add(item); onDone?.(); }} className="flex items-center gap-2 rounded-full bg-[#3C2923] px-5 py-3 text-sm font-bold text-[#FFF7ED] transition-colors hover:bg-[#B86942]" data-testid={`button-modal-add-${item.id}`}><Plus size={16} /> Ajouter au panier</button>; }

function GiftPage() {
  const [selected, setSelected] = useState<GiftBox | null>(null); const [note, setNote] = useState(""); const { add } = useShop();
  const addBox = () => { if (!selected) return; add({ id: selected.id, name: selected.name, price: selected.price, kind: "gift-box", tone: selected.tone, detail: selected.subtitle, note }); setSelected(null); setNote(""); };
  return <><section className="relative mx-auto grid max-w-7xl items-center gap-10 px-5 pb-20 pt-16 md:grid-cols-[1fr_.88fr] md:px-10 md:pb-28 md:pt-24"><div><p className="mb-6 flex items-center gap-3 text-xs font-bold uppercase tracking-[.24em] text-[#B86942]"><span className="h-px w-9 bg-[#B86942]" />À offrir, à partager</p><h1 className="serif max-w-2xl text-[clamp(3.3rem,7vw,6.7rem)] font-medium leading-[.9] tracking-[-.055em]">Un cadeau<br />qui dit <em className="text-[#B86942]">je pense</em><br />à toi.</h1><p className="mt-7 max-w-md text-base leading-7 text-[#76584A]">Des cookies tout juste cuits, une jolie boîte, et votre message écrit avec soin. Pour les grandes occasions comme les petits « juste parce que ».</p><a href="#idees" className="mt-9 inline-flex items-center gap-3 rounded-full bg-[#3C2923] px-6 py-3.5 text-sm font-bold text-[#FFF7ED]" data-testid="link-gift-choose">Choisir un coffret <ArrowRight size={17} /></a></div><div className="relative mx-auto aspect-square w-full max-w-[500px]"><div className="absolute inset-[8%] rotate-6 rounded-[42%_58%_48%_52%] bg-[#E7A26C]" /><div className="absolute inset-[15%] -rotate-6 rounded-[55%_45%_52%_48%] bg-[#F3C88D] shadow-[18px_20px_0_rgba(60,41,35,.1)]" /><div className="absolute inset-[24%] grid place-items-center rounded-[2rem] bg-[#F8E5C4] shadow-[inset_0_-9px_0_rgba(60,41,35,.08)]"><Gift size={92} strokeWidth={1} className="text-[#B86942]" /><span className="hand absolute bottom-[18%] rotate-[-6deg] text-2xl text-[#B86942]">avec soin</span></div><span className="absolute right-[2%] top-[10%] grid h-16 w-16 -rotate-12 place-items-center rounded-full bg-[#A9C6A5] text-center text-[9px] font-bold uppercase leading-3 tracking-widest text-[#365348]">prêt à<br />offrir</span></div></section><section id="idees" className="bg-[#3C2923] px-5 py-20 text-[#F8F0E5] md:px-10 md:py-28"><div className="mx-auto max-w-7xl"><div className="flex flex-wrap items-end justify-between gap-5"><div><p className="mb-4 text-xs font-bold uppercase tracking-[.25em] text-[#E7A26C]">01 — Les coffrets</p><h2 className="serif text-5xl leading-[.95] tracking-[-.04em] md:text-7xl">Pour chaque<br /><em className="text-[#E7A26C]">attention.</em></h2></div><p className="max-w-xs text-sm leading-6 text-[#C6A999]">Choisissez la taille, ajoutez un mot doux, nous nous occupons du reste.</p></div><div className="mt-14 grid gap-6 lg:grid-cols-3">{boxes.map((box, index) => <article key={box.id} className={`relative rounded-[1.7rem] bg-[#FBF5ED] p-5 text-[#3C2923] shadow-[0_9px_0_rgba(0,0,0,.16)] ${index === 1 ? "lg:-translate-y-5" : ""}`} data-testid={`card-box-${box.id}`}><div className="rounded-[1.25rem] bg-[#EAD4BF] p-3"><BoxArt box={box} /></div><div className="px-1 pb-2 pt-6"><div className="flex items-start justify-between gap-3"><div><h3 className="serif text-2xl leading-tight">{box.name}</h3><p className="mt-1 text-xs font-bold uppercase tracking-[.12em] text-[#B86942]">{box.subtitle}</p></div><span className="text-sm font-bold text-[#B86942]">{euro(box.price)}</span></div><p className="mt-3 text-sm leading-6 text-[#806657]">{box.description}</p><button type="button" onClick={() => setSelected(box)} className="mt-5 flex w-full items-center justify-center gap-2 rounded-full bg-[#3C2923] py-3 text-sm font-bold text-[#FFF7ED] transition-colors hover:bg-[#B86942]" data-testid={`button-personalize-${box.id}`}>Personnaliser <Sparkles size={15} /></button></div></article>)}</div></div></section><section className="px-5 py-20 md:px-10 md:py-28"><div className="mx-auto grid max-w-7xl gap-12 md:grid-cols-[.8fr_1.2fr] md:items-center"><div><p className="mb-4 text-xs font-bold uppercase tracking-[.25em] text-[#B86942]">02 — Le petit mot</p><h2 className="serif text-5xl leading-[.95] tracking-[-.04em] md:text-7xl">Les mots<br />restent.<br /><em className="text-[#B86942]">Les miettes aussi.</em></h2></div><div className="relative rotate-[-2deg] bg-[#F4D8A9] p-8 shadow-[8px_10px_0_rgba(60,41,35,.1)] md:p-12"><p className="text-xs font-bold uppercase tracking-[.22em] text-[#9B6E55]">Une carte dans chaque boîte</p><p className="hand paper-lines mt-7 min-h-[105px] pb-3 text-2xl leading-7 text-[#684338]">Pour une personne<br />vraiment chouette.</p><div className="mt-7 flex items-center justify-between border-t border-[#684338]/20 pt-5 text-xs text-[#9B6E55]"><span>Votre message, écrit avec soin</span><Cookie size={20} /></div></div></div></section>{selected && <Dialog title={`Personnaliser ${selected.name}`} onClose={() => setSelected(null)}><p className="text-[10px] font-bold uppercase tracking-[.22em] text-[#B86942]">Personnaliser le cadeau</p><h3 className="serif mt-1 text-3xl">{selected.name}</h3><p className="mt-3 text-sm leading-6 text-[#806657]">{selected.description}</p><label className="mt-7 block text-sm font-bold text-[#684338]" htmlFor="gift-note">Votre petit mot <span className="font-normal text-[#9B6E55]">(facultatif)</span><textarea id="gift-note" value={note} onChange={(event) => setNote(event.target.value)} maxLength={180} placeholder={selected.note} className="hand mt-3 h-28 w-full resize-none rounded-xl border border-[#3C2923]/15 bg-[#F4D8A9] p-4 text-lg outline-none placeholder:text-[#9B6E55]/70 focus:border-[#B86942]" data-testid="input-gift-note" /><span className="mt-1 block text-right text-xs font-normal text-[#927362]">{note.length}/180</span></label><button type="button" onClick={addBox} className="mt-5 flex w-full items-center justify-center gap-2 rounded-full bg-[#B86942] py-4 text-sm font-bold text-[#FFF7ED]" data-testid="button-add-gift">Ajouter ce cadeau · {euro(selected.price)} <ArrowRight size={17} /></button></Dialog>}</>;
}

function CartDrawer({ onClose }: { onClose: () => void }) {
  const { cart, change, remove } = useShop();
  const total = cart.reduce((sum, item) => sum + item.price * item.quantity, 0);
  return <Dialog title="Votre panier" onClose={onClose}><div className="flex items-start justify-between border-b border-[#3C2923]/10 pb-5 pr-8"><div><p className="text-[10px] font-bold uppercase tracking-[.22em] text-[#B86942]">Sélection commune</p><h2 className="serif mt-1 text-3xl">Votre panier</h2><p className="mt-1 text-xs text-[#927362]">Cookies et coffrets réunis au même endroit</p></div></div>{cart.length === 0 ? <div className="flex flex-col items-center py-14 text-center"><ShoppingBag size={34} className="text-[#D3B7A1]" /><h3 className="serif mt-5 text-2xl">Votre panier est vide</h3><p className="mt-2 text-sm text-[#927362]">Une petite douceur vous attend.</p><Link href="/#boutique" onClick={onClose} className="mt-7 rounded-full bg-[#3C2923] px-6 py-3 text-sm font-bold text-[#FFF7ED]" data-testid="link-empty-cart-shop">Découvrir les cookies</Link></div> : <><div className="space-y-4 py-6">{cart.map((item) => <div key={`${item.kind}-${item.id}`} className="flex items-center gap-3 border-b border-[#3C2923]/10 pb-4" data-testid={`row-cart-${item.kind}-${item.id}`}><div className="grid h-14 w-14 shrink-0 place-items-center rounded-xl" style={{ backgroundColor: item.tone }}>{item.kind === "gift-box" ? <Gift size={25} className="text-[#F8E5C4]" /> : <Cookie size={25} className="text-[#F8D39B]" />}</div><div className="min-w-0 flex-1"><div className="flex items-center gap-2"><p className="serif truncate text-lg">{item.name}</p><span className="rounded-full bg-[#F1E2D1] px-2 py-0.5 text-[9px] font-bold uppercase tracking-wide text-[#927362]">{item.kind === "gift-box" ? "Coffret" : "Cookie"}</span></div><p className="text-xs text-[#B86942]">{euro(item.price)}</p><div className="mt-2 flex items-center gap-2"><button type="button" onClick={() => change(item, -1)} className="grid h-7 w-7 place-items-center rounded-full border border-[#3C2923]/20" aria-label={`Retirer un ${item.name}`} data-testid={`button-decrease-${item.id}`}><Minus size={12} /></button><span className="w-4 text-center text-xs font-bold" data-testid={`text-quantity-${item.id}`}>{item.quantity}</span><button type="button" onClick={() => change(item, 1)} className="grid h-7 w-7 place-items-center rounded-full border border-[#3C2923]/20" aria-label={`Ajouter un ${item.name}`} data-testid={`button-increase-${item.id}`}><Plus size={12} /></button></div></div><button type="button" onClick={() => remove(item)} className="rounded-full p-2 text-[#B86942] hover:bg-[#F1E2D1]" aria-label={`Supprimer ${item.name}`} data-testid={`button-remove-${item.id}`}><Trash2 size={16} /></button></div>)}</div><div className="border-t border-[#3C2923]/10 pt-5"><div className="flex justify-between text-sm text-[#806657]"><span>Sous-total</span><strong className="text-lg text-[#3C2923]" data-testid="text-cart-total">{euro(total)}</strong></div><p className="mt-3 text-xs leading-5 text-[#927362]">Cette sélection est une intention de commande. Le paiement et la confirmation seront réalisés après échange, lorsqu'un système de commande sera connecté.</p><Link href="/contact" onClick={onClose} className="mt-5 flex w-full items-center justify-center gap-2 rounded-full bg-[#B86942] py-4 text-sm font-bold text-[#FFF7ED]" data-testid="link-checkout">Décrire ma commande <ArrowRight size={17} /></Link></div></>}</Dialog>;
}

function CheckoutPage() {
  const { cart } = useShop();
  const [sent, setSent] = useState(false);
  const [errors, setErrors] = useState<Record<string, string>>({});
  const [form, setForm] = useState({ name: "", email: "", address: "", message: "" });
  const total = cart.reduce((sum, item) => sum + item.price * item.quantity, 0);
  const submit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const next: Record<string, string> = {};
    if (!form.name.trim()) next.name = "Indiquez votre nom.";
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(form.email)) next.email = "Indiquez une adresse e-mail valide.";
    if (!form.address.trim()) next.address = "Indiquez l'adresse ou le lieu souhaité.";
    setErrors(next);
    if (Object.keys(next).length === 0) setSent(true);
  };
  return <section className="mx-auto max-w-6xl px-5 py-16 md:px-10 md:py-24"><div className="max-w-2xl"><p className="text-xs font-bold uppercase tracking-[.25em] text-[#B86942]">Votre demande</p><h1 className="serif mt-4 text-5xl leading-[.95] md:text-7xl">Parlons de<br /><em className="text-[#B86942]">votre fournée.</em></h1><p className="mt-6 max-w-xl text-base leading-7 text-[#76584A]">Nous recueillons uniquement les informations nécessaires pour préparer une éventuelle commande. Cette version ne transmet encore aucune donnée et aucun paiement n'est effectué.</p></div>{sent ? <div className="mt-12 rounded-[1.6rem] bg-[#A9C6A5] p-8 text-[#365348] md:p-12" role="status" data-testid="status-request-sent"><Check size={30} /><h2 className="serif mt-5 text-3xl">Votre demande est préparée.</h2><p className="mt-3 max-w-xl leading-7">Les champs ont été validés dans votre navigateur, mais aucune donnée n'a été transmise. Un moyen de contact sécurisé doit être configuré avant d'utiliser ce formulaire avec de vrais clients.</p><Link href="/" className="mt-7 inline-flex rounded-full bg-[#365348] px-5 py-3 text-sm font-bold text-[#F8F0E5]" data-testid="link-request-home">Retourner à la boutique</Link></div> : <div className="mt-12 grid gap-10 lg:grid-cols-[1fr_.7fr]"><form onSubmit={submit} noValidate className="rounded-[1.6rem] bg-[#FBF5ED] p-6 shadow-[0_8px_0_rgba(60,41,35,.06)] md:p-9" aria-describedby="request-disclaimer"><div className="grid gap-5 sm:grid-cols-2"><Field id="name" label="Nom et prénom" value={form.name} onChange={(value) => setForm({ ...form, name: value })} error={errors.name} required /><Field id="email" label="Adresse e-mail" type="email" value={form.email} onChange={(value) => setForm({ ...form, email: value })} error={errors.email} required /></div><Field id="address" label="Adresse ou lieu souhaité" hint="Pour estimer la remise ou la livraison, sans engagement." value={form.address} onChange={(value) => setForm({ ...form, address: value })} error={errors.address} required /><label className="mt-5 block text-sm font-bold text-[#684338]" htmlFor="message">Précision utile <span className="font-normal text-[#9B6E55]">(facultatif)</span><textarea id="message" value={form.message} onChange={(event) => setForm({ ...form, message: event.target.value })} rows={4} maxLength={800} className="mt-2 w-full resize-y rounded-xl border border-[#3C2923]/15 bg-[#F8F0E5] p-3.5 text-sm font-normal outline-none focus:border-[#B86942]" placeholder="Date souhaitée, occasion, allergie à signaler…" data-testid="input-message" /></label><p id="request-disclaimer" className="mt-5 rounded-xl bg-[#F1E2D1] p-3 text-xs leading-5 text-[#806657]">Ce formulaire ne transmet encore aucune donnée. Il sert uniquement à vérifier la saisie localement. Il n'y a ni paiement, ni commande ferme, ni promesse de disponibilité.</p><button type="submit" className="mt-6 flex w-full items-center justify-center gap-2 rounded-full bg-[#3C2923] py-4 text-sm font-bold text-[#FFF7ED] hover:bg-[#B86942]" data-testid="button-submit-request">Préparer ma demande <ArrowRight size={17} /></button></form><aside className="h-fit rounded-[1.6rem] bg-[#3C2923] p-7 text-[#F8F0E5] md:p-8"><p className="text-xs font-bold uppercase tracking-[.22em] text-[#E7A26C]">Votre sélection</p>{cart.length ? <div className="mt-6 space-y-4">{cart.map((item) => <div key={`${item.kind}-${item.id}`} className="flex justify-between gap-4 border-b border-[#F8F0E5]/15 pb-3 text-sm"><span>{item.quantity} × {item.name}</span><strong>{euro(item.price * item.quantity)}</strong></div>)}<div className="flex justify-between pt-2 text-base"><span>Total indicatif</span><strong>{euro(total)}</strong></div></div> : <p className="mt-6 text-sm leading-6 text-[#C6A999]">Votre panier est vide. Vous pouvez tout de même préparer une question.</p>}<p className="mt-8 text-xs leading-5 text-[#C6A999]">Le panier est conservé uniquement dans ce navigateur, via localStorage.</p></aside></div>}</section>;
}
function Field({ id, label, value, onChange, error, hint, type = "text", required = false }: { id: string; label: string; value: string; onChange: (value: string) => void; error?: string; hint?: string; type?: string; required?: boolean }) {
  return <label className="mt-5 block text-sm font-bold text-[#684338]" htmlFor={id}>{label} {required && <span aria-hidden="true" className="text-[#B86942]">*</span>}{hint && <span className="mt-1 block text-xs font-normal text-[#927362]">{hint}</span>}<input id={id} type={type} value={value} required={required} aria-invalid={Boolean(error)} aria-describedby={error ? `${id}-error` : undefined} onChange={(event) => onChange(event.target.value)} className={`mt-2 w-full rounded-xl border ${error ? "border-[#A94D43]" : "border-[#3C2923]/15"} bg-[#F8F0E5] px-3.5 py-3 text-sm font-normal outline-none focus:border-[#B86942]`} data-testid={`input-${id}`} />{error && <span id={`${id}-error`} role="alert" className="mt-1 block text-xs font-normal text-[#A94D43]">{error}</span>}</label>;
}

const legalContent: Record<string, { title: string; intro: string; sections: [string, string][] }> = {
  "/confidentialite": { title: "Politique de confidentialité", intro: "Cette page indique qui est responsable et quelles données peuvent être utilisées. Dans la version actuelle, aucune donnée de formulaire ne quitte votre navigateur.", sections: [["Responsable du traitement", "Le responsable indiqué pour cette boutique est Crockies, Route du Château 14, 1772 Nierlet-les-Bois, Fribourg. Contact : contact.crockies@gmail.com."], ["Données traitées", "Le panier est conservé localement dans votre navigateur. Le formulaire peut vérifier localement votre nom, votre adresse e-mail, une adresse ou un lieu souhaité et un message facultatif, mais cette version ne les transmet à aucun serveur et ne crée aucun compte client."], ["Finalités et durée", "Si un moyen de contact est ajouté plus tard, ces données devront servir uniquement à répondre à votre demande et préparer une éventuelle commande. La durée de conservation, les destinataires et les éventuels sous-traitants devront être documentés avant activation."], ["Droits", "Selon la LPD suisse, vous pouvez demander l'accès, la rectification ou la suppression de vos données et poser toute question sur leur traitement. Contactez Crockies à contact.crockies@gmail.com."] ] },
  "/cookies": { title: "Cookies et stockage local", intro: "La boutique privilégie une expérience sobre : aucun outil d'analyse, de publicité ou de suivi tiers n'est activé.", sections: [["Nécessaire au panier", "Le panier partagé est conservé uniquement dans le localStorage de votre navigateur, sous la clé technique de la boutique. Il permet de retrouver votre sélection entre les pages. Ces données ne sont pas envoyées à un service tiers depuis cette interface."], ["Cookies optionnels", "Il n'y a actuellement aucun cookie optionnel, aucune régie publicitaire et aucun outil d'analytics actif. Le bandeau et les réglages informent donc surtout de l'absence de traceurs optionnels et préparent un choix explicite si cela change."], ["Votre choix", "Vous pouvez modifier votre choix à tout moment via le bouton « Réglages de confidentialité » en bas de page. Le retrait des options ne supprime pas le stockage strictement nécessaire au panier, qui peut être effacé depuis les réglages du navigateur."] ] },
  "/conditions": { title: "Conditions de vente et d'utilisation", intro: "Document de travail à compléter avant toute mise en ligne commerciale. Cette interface prépare une intention de commande et ne constitue pas encore un tunnel de paiement.", sections: [["Vendeur, prix et zone", "Le vendeur est Crockies, Route du Château 14, 1772 Nierlet-les-Bois, Fribourg, contact.crockies@gmail.com. Les prix affichés sont en francs suisses (CHF). La zone annoncée est Fribourg ; les modalités exactes de livraison, de retrait, les délais et les frais doivent encore être confirmés avant toute vente."], ["Demande de commande", "Le formulaire actuel valide uniquement la saisie dans votre navigateur et ne transmet rien. Il ne confirme ni disponibilité, ni prix final, ni paiement. Une commande ne pourra devenir ferme qu'après confirmation explicite et mise en place d'un moyen de paiement réel."], ["Canton de Fribourg et denrées alimentaires", "Si l'activité est exercée dans le canton de Fribourg, le responsable doit vérifier les démarches d'annonce, d'autocontrôle, d'étiquetage et d'hygiène auprès du service cantonal compétent, ainsi que les obligations liées à la forme juridique et au registre du commerce. Consultez les informations officielles de l'État de Fribourg avant la mise sur le marché."], ["Responsabilité client", "Le client doit vérifier les informations communiquées et signaler toute allergie ou contrainte pertinente. Les listes d'ingrédients affichées ne remplacent pas un échange avec le fabricant en cas d'allergie sévère."] ] },
  "/remboursements": { title: "Livraison, retours et remboursements", intro: "Les modalités ci-dessous restent à finaliser pour les commandes dans le canton de Fribourg. Elles ne remplacent pas une politique commerciale validée pour les produits alimentaires.", sections: [["Produits alimentaires", "En raison de leur nature et de leur durée de conservation, les cookies peuvent être soumis à des règles particulières concernant l'annulation et le retour. Les exceptions et les produits endommagés doivent être définis clairement avant publication."], ["Livraison", "La zone actuellement annoncée est Fribourg. Les communes desservies, le retrait éventuel à Route du Château 14, 1772 Nierlet-les-Bois, les délais et les frais doivent être confirmés avant toute commande."], ["Réclamation", "En cas de problème, écrivez à contact.crockies@gmail.com avec la référence de l'échange, la date et des photos utiles."], ["Remboursement", "Les délais, le moyen de remboursement et les frais applicables doivent être fixés et affichés dans une version finale des conditions, après vérification juridique."] ] },
};
function LegalPage({ path }: { path: string }) {
  const content = legalContent[path];
  return <section className="mx-auto max-w-4xl px-5 py-16 md:px-10 md:py-24"><p className="text-xs font-bold uppercase tracking-[.25em] text-[#B86942]">Informations responsables</p><h1 className="serif mt-4 text-5xl leading-[.95] md:text-7xl">{content.title}</h1><p className="mt-7 max-w-2xl text-lg leading-8 text-[#76584A]">{content.intro}</p><div className="mt-10 rounded-2xl border border-[#B86942]/30 bg-[#F4D8A9] p-5 text-sm leading-6 text-[#684338]"><strong>À vérifier avant toute vente :</strong> ces informations sont une trame prudente basée sur la LPD suisse et les informations usuelles du commerce électronique. Faites-les relire par un professionnel du droit suisse et confirmez les modalités commerciales restantes.</div><div className="mt-12 grid gap-8">{content.sections.map(([heading, text]) => <article key={heading} className="border-t border-[#3C2923]/15 pt-6"><h2 className="serif text-3xl">{heading}</h2><p className="mt-3 max-w-3xl leading-7 text-[#76584A]">{text}</p></article>)}</div></section>;
}
function ContactPage() { return <section className="mx-auto max-w-4xl px-5 py-16 md:px-10 md:py-24"><p className="text-xs font-bold uppercase tracking-[.25em] text-[#B86942]">Parlons cookies</p><h1 className="serif mt-4 text-5xl leading-[.95] md:text-7xl">Une question,<br /><em className="text-[#B86942]">un projet.</em></h1><p className="mt-7 max-w-2xl text-lg leading-8 text-[#76584A]">Écrivez à Crockies pour une demande de coffret, une question sur les recettes ou une collaboration. Cette page affiche les coordonnées publiques, mais le formulaire reste local tant qu'aucun canal sécurisé n'est connecté.</p><div className="mt-10 rounded-[1.7rem] bg-[#3C2923] p-7 text-[#F8F0E5] md:p-10"><p className="text-xs font-bold uppercase tracking-[.2em] text-[#E7A26C]">Crockies</p><h2 className="serif mt-4 text-3xl">Route du Château 14<br />1772 Nierlet-les-Bois, Fribourg</h2><a href="mailto:contact.crockies@gmail.com" className="mt-5 inline-block text-[#E7A26C] underline underline-offset-4">contact.crockies@gmail.com</a><p className="mt-5 max-w-xl text-sm leading-6 text-[#C6A999]">Aucune commande n'est confirmée par e-mail depuis cette page. Les conditions de livraison, les délais et le paiement doivent être convenus avant la vente.</p><Link href="/commande" className="mt-7 inline-flex items-center gap-2 rounded-full bg-[#E7A26C] px-5 py-3 text-sm font-bold text-[#3C2923]" data-testid="link-contact-request">Préparer une demande <ArrowRight size={17} /></Link></div></section>; }

function CookieConsent() {
  const [show, setShow] = useState(false); const [settings, setSettings] = useState(false); const [optional, setOptional] = useState(false);
  useEffect(() => { const saved = localStorage.getItem("crockies-cookie-choice"); if (!saved) setShow(true); const open = () => setSettings(true); window.addEventListener("open-cookie-settings", open); return () => window.removeEventListener("open-cookie-settings", open); }, []);
  const save = (allow: boolean) => { localStorage.setItem("crockies-cookie-choice", JSON.stringify({ optional: allow, at: new Date().toISOString() })); setShow(false); setSettings(false); };
  if (!show && !settings) return null;
  return settings ? <Dialog title="Réglages de confidentialité" onClose={() => setSettings(false)}><p className="text-[10px] font-bold uppercase tracking-[.22em] text-[#B86942]">Votre choix</p><h2 className="serif mt-2 text-3xl">Des réglages sans surprise.</h2><p className="mt-4 text-sm leading-6 text-[#76584A]">Le panier local est nécessaire à la boutique et ne peut pas être désactivé depuis cette interface. Aucun analytics ni publicité n'est activé.</p><label className="mt-6 flex items-start gap-3 rounded-xl bg-[#F1E2D1] p-4 text-sm"><input type="checkbox" checked disabled className="mt-1 accent-[#B86942]" /><span><strong>Panier local</strong><br /><span className="text-xs text-[#806657]">Nécessaire, stocké uniquement sur cet appareil.</span></span></label><label className="mt-3 flex items-start gap-3 rounded-xl border border-[#3C2923]/10 p-4 text-sm"><input type="checkbox" checked={optional} onChange={(event) => setOptional(event.target.checked)} className="mt-1 accent-[#B86942]" data-testid="checkbox-optional-cookies" /><span><strong>Cookies optionnels</strong><br /><span className="text-xs text-[#806657]">Aucun service optionnel n'est chargé actuellement.</span></span></label><button type="button" onClick={() => save(optional)} className="mt-6 w-full rounded-full bg-[#3C2923] py-3.5 text-sm font-bold text-[#FFF7ED]" data-testid="button-save-cookie-settings">Enregistrer mon choix</button></Dialog> : <div className="fixed bottom-4 left-4 right-4 z-40 mx-auto max-w-4xl rounded-[1.4rem] border border-[#3C2923]/10 bg-[#FBF5ED] p-5 shadow-2xl md:flex md:items-center md:gap-7" role="dialog" aria-label="Choix de confidentialité" data-testid="banner-cookie-consent"><div className="flex-1"><p className="text-sm font-bold text-[#3C2923]">Votre vie privée compte.</p><p className="mt-1 text-xs leading-5 text-[#806657]">Le panier fonctionne avec le stockage local de votre navigateur. Aucun outil d'analyse ou de publicité n'est activé. Les cookies optionnels sont refusés par défaut.</p></div><div className="mt-4 flex shrink-0 gap-2 md:mt-0"><button type="button" onClick={() => save(false)} className="rounded-full border border-[#3C2923]/20 px-4 py-2.5 text-xs font-bold" data-testid="button-refuse-optional">Continuer sans option</button><button type="button" onClick={() => setSettings(true)} className="rounded-full bg-[#3C2923] px-4 py-2.5 text-xs font-bold text-[#FFF7ED]" data-testid="button-cookie-settings">Réglages</button></div></div>;
}

function Meta({ title, description }: { title: string; description: string }) {
  useEffect(() => { document.title = title; const set = (selector: string, content: string, attr = "content") => { const el = document.querySelector<HTMLMetaElement>(selector); if (el) el.setAttribute(attr, content); }; set('meta[name="description"]', description); set('meta[property="og:title"]', title); set('meta[property="og:description"]', description); set('meta[property="og:url"]', `https://crockies.ch${window.location.pathname}`); let canonical = document.querySelector<HTMLLinkElement>('link[rel="canonical"]'); if (!canonical) { canonical = document.createElement("link"); canonical.rel = "canonical"; document.head.appendChild(canonical); } canonical.href = `https://crockies.ch${window.location.pathname}`; }, [title, description]); return null;
}

const queryClient = new QueryClient();
function Router() {
  const [location] = useLocation(); const [cart, setCart] = useState<CartItem[]>(() => readCart()); const [cartOpen, setCartOpen] = useState(false);
  useEffect(() => subscribeToCart(() => setCart(readCart())), []);
  const shop = useMemo<ShopContextValue>(() => ({ cart, openCart: () => setCartOpen(true), add: (item) => { const current = readCart(); const existing = current.find((entry) => entry.id === item.id && entry.kind === item.kind); const next = existing ? current.map((entry) => entry.id === item.id && entry.kind === item.kind ? { ...entry, quantity: entry.quantity + 1 } : entry) : [...current, { ...item, quantity: 1 }]; writeCart(next); setCart(next); }, change: (item, delta) => { const next = readCart().flatMap((entry) => entry.id === item.id && entry.kind === item.kind ? (entry.quantity + delta > 0 ? [{ ...entry, quantity: entry.quantity + delta }] : []) : [entry]); writeCart(next); setCart(next); }, remove: (item) => { const next = readCart().filter((entry) => !(entry.id === item.id && entry.kind === item.kind)); writeCart(next); setCart(next); } }), [cart]);
  const path = location.split("?")[0];
  const titleMap: Record<string, [string, string]> = { "/": ["Cookies faits maison en Suisse | Délices Cookies", "Cookies généreux, coffrets cadeaux et petites attentions préparés avec soin."], "/coffrets": ["Coffrets cadeaux de cookies | Délices Cookies", "Offrez un coffret de cookies fait maison, avec un message personnalisé."], "/contact": ["Contact et demande de commande | Délices Cookies", "Une question ou une demande de coffret ? Écrivez à Crockies."], "/confidentialite": ["Politique de confidentialité | Délices Cookies", "Informations sur les données utilisées par Crockies."], "/cookies": ["Cookies et stockage local | Délices Cookies", "Découvrez le fonctionnement du panier local et des cookies optionnels."], "/conditions": ["Conditions de vente | Délices Cookies", "Cadre d'information pour les demandes de commande Crockies."], "/remboursements": ["Livraison et remboursements | Délices Cookies", "Informations sur les retours, livraisons et remboursements."], "/commande": ["Votre demande de commande | Délices Cookies", "Préparez une intention de commande sans paiement en ligne."] };
  const [title, description] = titleMap[path] ?? ["Délices Cookies", "Cookies faits maison et coffrets gourmands."];
  return <ShopContext.Provider value={shop}><Meta title={title} description={description} /><Shell><Switch><Route path="/" component={HomePage} /><Route path="/coffrets" component={GiftPage} /><Route path="/commande" component={CheckoutPage} /><Route path="/contact" component={ContactPage} /><Route path="/confidentialite">{() => <LegalPage path="/confidentialite" />}</Route><Route path="/cookies">{() => <LegalPage path="/cookies" />}</Route><Route path="/conditions">{() => <LegalPage path="/conditions" />}</Route><Route path="/remboursements">{() => <LegalPage path="/remboursements" />}</Route><Route component={NotFound} /></Switch></Shell>{cartOpen && <CartDrawer onClose={() => setCartOpen(false)} />}</ShopContext.Provider>;
}
function RoutedErrorBoundary() {
  const [location] = useLocation();
  return <ErrorBoundary resetKey={location}><Router /></ErrorBoundary>;
}
function App() { return <QueryClientProvider client={queryClient}><TooltipProvider><WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/, "")}><RoutedErrorBoundary /></WouterRouter><Toaster /></TooltipProvider></QueryClientProvider>; }
export default App;